const object=x=>x&&typeof x==='object'&&!Array.isArray(x)?x:{};
const integer=(x,min,max,fallback=0)=>Number.isInteger(x)&&x>=min&&x<=max?x:fallback;
const text=(x,max)=>typeof x==='string'?x.slice(0,max):'';
export function cleanTask(raw){const x=object(raw);return {work:text(x.work,20000),attempted:x.attempted===true,revealed:x.attempted===true&&x.revealed===true};}
export function cleanLesson(lesson,practice,raw){const x=object(raw),questions=[lesson.quiz,...practice.quizzes],tabs=['theory','quiz','debug','practice'];
 const s={tab:tabs.includes(x.tab)?x.tab:'theory',quizIndex:integer(x.quizIndex,0,questions.length-1),quizChoices:[],quizAttempts:[],quizResults:[],debugAttempts:integer(x.debugAttempts,0,10000),line:integer(x.line,1,lesson.bug.code.split('\n').length,null),category:['Syntax','Logic','Calculation','Boundary','Initialisation','Design'].includes(x.category)?x.category:'',correction:integer(x.correction,0,lesson.bug.options.length-1,null),debugChecked:x.debugChecked===true,debugFeedback:text(x.debugFeedback,500),debugHintShown:x.debugHintShown===true,debugRevealed:x.debugRevealed===true,taskIndex:integer(x.taskIndex,0,practice.tasks.length-1),taskWork:{},taskAttempt:{},taskReveal:{}};
 questions.forEach((q,i)=>{s.quizChoices[i]=integer(x.quizChoices?.[i],0,q.options.length-1,null);s.quizAttempts[i]=x.quizAttempts?.[i]===true&&s.quizChoices[i]!==null;s.quizResults[i]=s.quizAttempts[i]&&s.quizChoices[i]===q.correct;});s.quizPassed=s.quizResults.every(Boolean);
 s.bugPassed=s.debugChecked&&s.debugAttempts>0&&s.line===lesson.bug.line&&s.category===lesson.bug.category&&s.correction===lesson.bug.correct;s.debugHintShown=s.debugAttempts>0&&s.debugHintShown;s.debugRevealed=s.debugAttempts>0&&s.debugRevealed;
 for(const t of practice.tasks){s.taskWork[t.id]=text(object(x.taskWork)[t.id],10000);s.taskAttempt[t.id]=object(x.taskAttempt)[t.id]===true;s.taskReveal[t.id]=s.taskAttempt[t.id]&&object(x.taskReveal)[t.id]===true;}
 return s;
}
export function cleanActivity(a,raw){const x=object(raw);const order=a.statements&&Array.isArray(x.order)&&x.order.length===a.statements.length&&new Set(x.order).size===x.order.length&&x.order.every(i=>Number.isInteger(i)&&i>=0&&i<a.statements.length)?[...x.order]:a.initialOrder?[...a.initialOrder]:null;const attempts=integer(x.attempts,0,10000);return {answer:a.choices?integer(x.answer,0,a.choices.length-1,null):null,order,moved:x.moved===true,hints:integer(x.hints,0,2),attempts,feedback:text(x.feedback,300),revealed:attempts>0&&x.revealed===true};}
export function cleanDraft(raw,max=100000){const x=object(raw);return {code:text(x.code,max),type:x.type==='hierarchy'?'hierarchy':'flow',preset:text(x.preset,80)};}
